373:               this.setLoading(false);
374:               this.cerrarAlertaCarga();
375:               this.popUpManager.showErrorAlert(this.translate.instant('formulario_pagador.ERROR.inactivar_registro'));
376:             } else {
377:               this.manejarError(error, 'formulario_pagador.ERROR.actualizar_pagador');
378:             }
379:             reject(error);
380:           });
381:       } else {
382:         // Crear nuevo registro
383:         this.crearNuevoRegistro(numeroRecibo)
384:           .then(() => {
385:             this.setLoading(false);
386:             this.cerrarAlertaCarga();
